{
  "system_name": "Distributed LRU Cache Layer for Microservices",
  "overview": "A two-tier caching architecture combining a high-performance in-process LRU cache (L1) backed by a distributed Redis cluster (L2) to serve cached data with sub-millisecond local latency and cross-instance consistency. The system is designed as a sidecar-compatible, non-blocking cache layer that degrades gracefully when the distributed backend is unavailable, ensuring microservice resilience. Metrics, TTL enforcement, and invalidation are first-class concerns integrated with Prometheus and OpenTelemetry.",
  "components": [
    {
      "name": "L1 In-Process LRU Cache",
      "responsibility": "Provides sub-millisecond, thread-safe, bounded LRU caching local to each microservice instance using Caffeine (JVM). Enforces maximum entry count, per-entry TTL, and exposes hit/miss/eviction metrics via Micrometer. Acts as the first lookup tier before delegating to L2.",
      "technology": "Caffeine Cache (JVM) / cachetools (Python) / lru-cache (Node.js) — language-matched; primary reference is Caffeine with AsyncLoadingCache and StatsCounter"
    },
    {
      "name": "L2 Distributed Cache (Redis Cluster)",
      "responsibility": "Provides a shared, cross-instance cache store for data consistency across horizontally scaled microservice replicas. Stores serialized cache entries with TTL enforced natively by Redis EXPIRE. Supports keyspace notifications for invalidation propagation and acts as fallback when L1 misses.",
      "technology": "Redis 7.x Cluster mode with TLS, deployed via Redis Operator on Kubernetes; Lettuce async client for non-blocking I/O"
    },
    {
      "name": "Cache Facade / Unified API",
      "responsibility": "Provides a single, technology-agnostic interface (get, put, invalidate, bulkInvalidate) consumed by microservice business logic. Orchestrates the L1 → L2 → origin lookup chain, handles circuit breaking on L2 failures, and abstracts serialization/deserialization of cache values.",
      "technology": "Java interface with Spring AOP-based @Cacheable integration; Resilience4j CircuitBreaker wrapping L2 calls; Jackson for JSON serialization with schema versioning"
    },
    {
      "name": "Cache Invalidation Bus",
      "responsibility": "Broadcasts key-level and bulk invalidation events across all microservice instances so that L1 caches on peer instances are invalidated when data changes. Ensures eventual consistency without requiring synchronous cross-instance calls.",
      "technology": "Redis Pub/Sub (keyspace notifications) for lightweight invalidation signals; fallback to Apache Kafka topic 'cache-invalidation-events' for durable, ordered bulk invalidation"
    },
    {
      "name": "Metrics & Observability Exporter",
      "responsibility": "Collects and exports cache operational metrics including hit rate, miss rate, eviction count, current size, L1/L2 latency histograms, and TTL expiry counts. Integrates distributed tracing spans around cache operations for end-to-end latency attribution.",
      "technology": "Micrometer with Prometheus registry for metrics scraping; OpenTelemetry Java Agent for trace context propagation; Grafana dashboard provisioned via ConfigMap"
    },
    {
      "name": "Cache Configuration Service",
      "responsibility": "Manages runtime-configurable cache parameters (max capacity, TTL, eviction policy, circuit breaker thresholds) without requiring service restarts. Validates configuration changes and propagates them to running instances. Enforces memory budget constraints per container resource limits.",
      "technology": "Spring Cloud Config Server backed by Git repository; Kubernetes ConfigMap with Reloader for zero-downtime config refresh; JSON Schema validation on config changes"
    },
    {
      "name": "PII Data Filter & Encryption Layer",
      "responsibility": "Intercepts cache put operations to detect and handle PII-tagged data fields. Applies field-level encryption before writing to L2 (Redis) and enforces data residency rules by routing sensitive keys to region-specific Redis clusters. Prevents raw PII from persisting in distributed cache.",
      "technology": "Custom CacheInterceptor using annotation-driven PII tagging (@SensitiveCache); AES-256-GCM encryption via AWS KMS or HashiCorp Vault Transit Engine; regional Redis endpoint routing map"
    },
    {
      "name": "Origin Data Loader",
      "responsibility": "Executes the actual downstream data fetch (database query or external API call) on a full cache miss (L1 and L2 both miss). Integrates with Caffeine's AsyncCacheLoader pattern to prevent cache stampede via request coalescing. Returns data to the Cache Facade for population of both L1 and L2.",
      "technology": "Async CompletableFuture-based loader; HikariCP connection pool for DB calls; Resilience4j Bulkhead to isolate origin load from cache-hit traffic paths"
    }
  ],
  "api_endpoints": [
    {
      "method": "GET",
      "path": "/api/v1/cache/entries/{key}",
      "description": "Retrieves a cached value by key. Checks L1 first, then L2, then triggers origin load on full miss. Returns the value with metadata including TTL remaining, cache tier hit (L1/L2/ORIGIN), and entry age.",
      "request_body": null,
      "response_schema": {
        "key": "string",
        "value": "object (any serializable type)",
        "hit": "boolean",
        "tier": "enum: L1 | L2 | ORIGIN | MISS",
        "ttl_remaining_ms": "integer",
        "fetched_at": "ISO8601 timestamp"
      },
      "status_codes": {
        "200": "Cache hit or origin-loaded value returned",
        "204": "Cache miss and origin returned no data",
        "400": "Invalid or malformed key",
        "503": "L2 unavailable and L1 miss; circuit open"
      }
    },
    {
      "method": "PUT",
      "path": "/api/v1/cache/entries/{key}",
      "description": "Inserts or updates a cache entry in both L1 and L2. Accepts optional per-entry TTL override. If capacity is exceeded, LRU eviction is triggered on L1; Redis handles its own eviction policy. PII filter is applied before L2 write.",
      "request_body": {
        "value": "object (serializable)",
        "ttl_ms": "integer (optional, overrides global TTL)",
        "tags": "array of string (optional, for bulk invalidation grouping)",
        "sensitive": "boolean (optional, triggers PII encryption path)"
      },
      "response_schema": {
        "key": "string",
        "stored": "boolean",
        "evicted_key": "string or null (key evicted to make room)",
        "effective_ttl_ms": "integer"
      },
      "status_codes": {
        "200": "Entry inserted or updated successfully",
        "400": "Invalid key, value not serializable, or TTL out of range",
        "507": "Cache at hard memory limit; entry rejected"
      }
    },
    {
      "method": "DELETE",
      "path": "/api/v1/cache/entries/{key}",
      "description": "Invalidates a single cache entry across L1 on the local instance and publishes an invalidation event to the Cache Invalidation Bus so all peer instances remove the key from their L1 caches and L2 is deleted.",
      "request_body": null,
      "response_schema": {
        "key": "string",
        "invalidated_l1": "boolean",
        "invalidated_l2": "boolean",
        "broadcast_sent": "boolean"
      },
      "status_codes": {
        "200": "Key invalidated successfully",
        "404": "Key not found in any cache tier",
        "400": "Invalid key format"
      }
    },
    {
      "method": "POST",
      "path": "/api/v1/cache/invalidate/bulk",
      "description": "Performs bulk invalidation by key list or tag group. Publishes a durable Kafka invalidation event for cross-instance propagation. Suitable for invalidating all entries related to a specific entity (e.g., all cache keys tagged 'user:123').",
      "request_body": {
        "keys": "array of string (optional)",
        "tags": "array of string (optional, invalidates all keys with matching tags)",
        "pattern": "string (optional, glob pattern for key matching — use with caution)"
      },
      "response_schema": {
        "invalidated_count": "integer",
        "keys_invalidated": "array of string",
        "broadcast_event_id": "string (Kafka message ID)"
      },
      "status_codes": {
        "200": "Bulk invalidation completed",
        "400": "Neither keys, tags, nor pattern provided",
        "207": "Partial success — some keys failed to invalidate in L2"
      }
    },
    {
      "method": "GET",
      "path": "/api/v1/cache/metrics",
      "description": "Returns current operational metrics for the cache layer on this instance including hit/miss rates, eviction counts, current L1 size, L2 connectivity status, and latency percentiles. Intended for dashboards and alerting; Prometheus scrape endpoint is separate at /actuator/prometheus.",
      "request_body": null,
      "response_schema": {
        "instance_id": "string",
        "l1_hit_count": "integer",
        "l1_miss_count": "integer",
        "l2_hit_count": "integer",
        "l2_miss_count": "integer",
        "origin_load_count": "integer",
        "eviction_count": "integer",
        "current_l1_size": "integer",
        "l1_max_capacity": "integer",
        "hit_rate_percent": "float",
        "l1_get_p99_ms": "float",
        "l2_get_p99_ms": "float",
        "l2_circuit_state": "enum: CLOSED | OPEN | HALF_OPEN",
        "ttl_expiry_count": "integer"
      },
      "status_codes": {
        "200": "Metrics returned successfully"
      }
    },
    {
      "method": "GET",
      "path": "/api/v1/cache/health",
      "description": "Returns health status of the cache layer including L1 memory pressure, L2 Redis connectivity, circuit breaker state, and configuration validity. Used by Kubernetes liveness/readiness probes and load balancer health checks. Cache failure does NOT cause unhealthy status — only degraded.",
      "request_body": null,
      "response_schema": {
        "status": "enum: HEALTHY | DEGRADED | UNHEALTHY",
        "l1_status": "enum: OK | MEMORY_PRESSURE",
        "l2_status": "enum: CONNECTED | DISCONNECTED | CIRCUIT_OPEN",
        "config_valid": "boolean",
        "uptime_seconds": "integer",
        "degraded_reasons": "array of string"
      },
      "status_codes": {
        "200": "Cache layer healthy or degraded but operational",
        "503": "Cache layer in a state that may impact service (rare — only if L1 also fails)"
      }
    }
  ],
  "data_models": [
    {
      "name": "CacheEntry",
      "fields": {
        "key": "string, required, max 512 bytes, URL-safe characters only",
        "value": "bytes (serialized), required, max configurable (default 1MB per entry)",
        "created_at": "epoch milliseconds, immutable after creation",
        "last_accessed_at": "epoch milliseconds, updated on every get (drives LRU ordering)",
        "expires_at": "epoch milliseconds, nullable (null = no TTL expiry, LRU-only eviction)",
        "ttl_ms": "integer, nullable, per-entry TTL override in milliseconds",
        "tags": "array of string, optional, used for bulk tag-based invalidation",
        "version": "integer, monotonically increasing, used for optimistic concurrency on L2 updates",
        "sensitive": "boolean, default false, triggers PII encryption path on L2 write",
        "size_bytes": "integer, computed on write, used for memory budget tracking",
        "tier_origin": "enum: L1 | L2 | ORIGIN, records where value was sourced on last access"
      }
    },
    {
      "name": "CacheConfiguration",
      "fields": {
        "cache_name": "string, required, unique identifier for this cache instance",
        "max_capacity": "integer, required, maximum number of entries before LRU eviction triggers",
        "max_memory_mb": "integer, optional, memory-based capacity bound (overrides max_capacity if set)",
        "global_ttl_ms": "integer, nullable, default TTL applied to all entries unless overridden per-entry",
        "eviction_policy": "enum: LRU | LFU | TLRU (Time-aware LRU), default LRU",
        "l2_enabled": "boolean, default true, disables Redis tier if false (local-only mode)",
        "l2_redis_uri": "string, Redis cluster connection URI with TLS",
        "circuit_breaker_failure_threshold": "integer, default 5, failures before circuit opens",
        "circuit_breaker_wait_duration_ms": "integer, default 30000, time in OPEN state before HALF_OPEN",
        "metrics_enabled": "boolean, default true",
        "pii_encryption_enabled": "boolean, default false",
        "kms_key_id": "string, nullable, AWS KMS or Vault key ID for PII encryption",
        "invalidation_bus": "enum: REDIS_PUBSUB | KAFKA | NONE, default REDIS_PUBSUB"
      }
    },
