        "pattern": "string, nullable, glob pattern for PATTERN type",
        "source_instance_id": "string, ID of the microservice instance that originated the event",
        "issued_at": "epoch milliseconds",
        "cache_name": "string, scopes invalidation to a specific named cache",
        "reason": "string, optional, human-readable reason for audit logging (e.g., 'entity_updated', 'schema_migration')"
      }
    },
